import test from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdir, mkdtemp, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { sourceState } from "../server/core/source-state.mjs";
import { digest, writeJson } from "../server/core/files.mjs";

const MARKER =
  "// Generated by scripts/build-client.mjs at install. Do not edit or commit.";

async function checkout({ installBuildFiles, subdir } = {}) {
  const dir = await mkdtemp(path.join(tmpdir(), "paseo-source-state-"));
  const git = (...a) =>
    execFileSync("git", ["-c", "core.fsmonitor=false", "-C", dir, ...a], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    }).trim();
  git("init", "-q");
  git("config", "user.name", "Test");
  git("config", "user.email", "test@example.invalid");
  const plugRoot = subdir ? path.join(dir, subdir) : dir;
  await mkdir(path.join(plugRoot, "server"), { recursive: true });
  await writeFile(
    path.join(plugRoot, "server/tasks-chunk.ts"),
    "export const TASKS_CHUNK = null;\n",
  );
  if (installBuildFiles)
    await writeJson(path.join(plugRoot, "paseo-plugin.json"), {
      installBuildFiles,
    });
  git("add", ".");
  git("commit", "-qm", "initial");
  const row = {
    id: "better-paseo",
    path: plugRoot,
    installation: {
      identity: { kind: "git", remote: "https://example.invalid/demo.git" },
      currentRevision: git("rev-parse", "HEAD"),
    },
  };
  return { dir, git, row, profile: { patches: [] } };
}

test("a modified tracked file with the install-generated marker counts as clean", async () => {
  const f = await checkout();
  await writeFile(
    path.join(f.dir, "server/tasks-chunk.ts"),
    `${MARKER}\nexport const TASKS_CHUNK = { code: '"use strict";' };\n`,
  );
  const state = await sourceState(f.row, f.profile);
  assert.equal(state.clean, true);
  assert.deepEqual(state.changed, []);
});

test("a hand edit without the marker still counts as dirty", async () => {
  const f = await checkout();
  await writeFile(
    path.join(f.dir, "server/tasks-chunk.ts"),
    "export const TASKS_CHUNK = { hand: true };\n",
  );
  const state = await sourceState(f.row, f.profile);
  assert.equal(state.clean, false);
  assert.deepEqual(state.changed, ["server/tasks-chunk.ts"]);
});

test("an untracked file carrying the marker still counts as dirty", async () => {
  const f = await checkout();
  await writeFile(path.join(f.dir, "server/extra.ts"), `${MARKER}\nlocal\n`);
  const state = await sourceState(f.row, f.profile);
  assert.equal(state.clean, false);
  assert.deepEqual(state.changed, ["server/extra.ts"]);
});

test("installBuildFiles scoping excludes marker files outside the list", async () => {
  const f = await checkout({ installBuildFiles: ["server/other.ts"] });
  await writeFile(
    path.join(f.dir, "server/tasks-chunk.ts"),
    `${MARKER}\nexport const TASKS_CHUNK = { code: "..." };\n`,
  );
  const state = await sourceState(f.row, f.profile);
  assert.equal(state.clean, false);
  assert.deepEqual(state.changed, ["server/tasks-chunk.ts"]);
});

test("installBuildFiles scoping accepts a listed marker file as clean", async () => {
  const f = await checkout({
    installBuildFiles: ["server/tasks-chunk.ts"],
  });
  await writeFile(
    path.join(f.dir, "server/tasks-chunk.ts"),
    `${MARKER}\nexport const TASKS_CHUNK = { code: "..." };\n`,
  );
  const state = await sourceState(f.row, f.profile);
  assert.equal(state.clean, true);
  assert.deepEqual(state.changed, []);
});
test("installBuildFiles entries match when the plugin lives in a repository subdirectory", async () => {
  const f = await checkout({
    subdir: "plugins/demo",
    installBuildFiles: ["server/tasks-chunk.ts"],
  });
  await writeFile(
    path.join(f.dir, "plugins/demo/server/tasks-chunk.ts"),
    `${MARKER}\nexport const TASKS_CHUNK = { code: "..." };\n`,
  );
  // Git status reports names relative to the toplevel
  // ("plugins/demo/server/tasks-chunk.ts"), while the manifest declares
  // plugin-relative paths; the scope must normalize before matching.
  const state = await sourceState(f.row, f.profile);
  assert.equal(state.clean, true);
  assert.deepEqual(state.changed, []);
});

test("installed bundle directory sourceState detects file edits, additions, and deletions", async () => {
  const dir = await mkdtemp(path.join(tmpdir(), "paseo-bundle-source-state-"));
  try {
    await writeFile(path.join(dir, "paseo-plugin.json"), JSON.stringify({ id: "bundle-tool" }));
    await writeFile(path.join(dir, "index.js"), "console.log('v1');\n");
    const { fingerprintDirectory, BUNDLE_MARKER } = await import("../server/core/bundle.mjs");
    const initialFiles = await fingerprintDirectory(dir);
    const revision = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
    await writeFile(
      path.join(dir, BUNDLE_MARKER),
      JSON.stringify({
        source: "bundle:bundles/bundle-tool.tar.gz",
        revision,
        files: initialFiles,
      }),
    );
    const row = {
      id: "bundle-tool",
      path: dir,
      installation: {
        identity: { kind: "directory" },
      },
    };
    // 1. Clean
    let state = await sourceState(row, { patches: [] });
    assert.equal(state.clean, true);
    assert.equal(state.head, revision);
    assert.deepEqual(state.changed, []);

    // 2. Modified file
    await writeFile(path.join(dir, "index.js"), "console.log('edited');\n");
    state = await sourceState(row, { patches: [] });
    assert.equal(state.clean, false);
    assert.deepEqual(state.changed, ["index.js"]);

    // Revert index.js
    await writeFile(path.join(dir, "index.js"), "console.log('v1');\n");

    // 3. Added file
    await writeFile(path.join(dir, "extra.js"), "console.log('new');\n");
    state = await sourceState(row, { patches: [] });
    assert.equal(state.clean, false);
    assert.deepEqual(state.changed, ["extra.js"]);

    // Remove added file
    const { rm } = await import("node:fs/promises");
    await rm(path.join(dir, "extra.js"));

    // 4. Deleted file
    await rm(path.join(dir, "index.js"));
    state = await sourceState(row, { patches: [] });
    assert.equal(state.clean, false);
    assert.deepEqual(state.changed, ["index.js"]);
  } finally {
    const { rm } = await import("node:fs/promises");
    await rm(dir, { recursive: true, force: true });
  }
});

test("installed bundle directory sourceState recognizes recorded patches and detects subsequent edits", async () => {
  const dir = await mkdtemp(path.join(tmpdir(), "paseo-bundle-patch-source-state-"));
  try {
    await writeFile(path.join(dir, "paseo-plugin.json"), JSON.stringify({ id: "bundle-tool" }));
    await writeFile(path.join(dir, "index.js"), "console.log('original');\n");
    const { fingerprintDirectory, BUNDLE_MARKER } = await import("../server/core/bundle.mjs");
    const { digest } = await import("../server/core/files.mjs");
    const initialFiles = await fingerprintDirectory(dir);
    const revision = "1111222233334444555566667777888899990000aaaabbbbccccddddeeeeffff";
    await writeFile(
      path.join(dir, BUNDLE_MARKER),
      JSON.stringify({
        source: "bundle:bundles/bundle-tool.tar.gz",
        revision,
        files: initialFiles,
      }),
    );
    const row = {
      id: "bundle-tool",
      path: dir,
      installation: {
        identity: { kind: "directory" },
      },
    };

    // Apply a patch to index.js
    const patchedContent = "console.log('patched');\n";
    await writeFile(path.join(dir, "index.js"), patchedContent);
    const patchAfterSha256 = digest(Buffer.from(patchedContent));

    const profile = {
      patches: [
        {
          plugin: "bundle-tool",
          data: {
            files: [
              {
                path: "index.js",
                afterSha256: patchAfterSha256,
              },
            ],
          },
        },
      ],
    };

    // 1. Clean when file matches recorded patch
    let state = await sourceState(row, profile);
    assert.equal(state.clean, true);
    assert.deepEqual(state.changed, []);

    // 2. Dirty if patched file is further modified
    await writeFile(path.join(dir, "index.js"), "console.log('tampered');\n");
    state = await sourceState(row, profile);
    assert.equal(state.clean, false);
    assert.deepEqual(state.changed, ["index.js"]);

    // Revert to patch content -> clean again
    await writeFile(path.join(dir, "index.js"), patchedContent);
    state = await sourceState(row, profile);
    assert.equal(state.clean, true);

    // 3. Dirty if an unpatched file is added or changed
    await writeFile(path.join(dir, "extra.js"), "new file");
    state = await sourceState(row, profile);
    assert.equal(state.clean, false);
    assert.deepEqual(state.changed, ["extra.js"]);
  } finally {
    const { rm } = await import("node:fs/promises");
    await rm(dir, { recursive: true, force: true });
  }
});

test("the patch allowance survives a non-canonical (symlinked) checkout path", async () => {
  // A symlinked daemon home leaves row.path with a symlink prefix while
  // git canonicalizes its toplevel; keyed off the raw path the allowance
  // matched no status entry and read every patched file as dirty. The
  // linked root itself stays refused, so the alias is placed one level
  // above the checkout, as the daemon home is.
  const home = await mkdtemp(path.join(tmpdir(), "paseo-source-state-home-"));
  const dir = path.join(home, "plugins", "better-paseo", "1.0.0");
  await mkdir(path.join(dir, "server"), { recursive: true });
  const git = (...a) =>
    execFileSync("git", ["-c", "core.fsmonitor=false", "-C", dir, ...a], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
    }).trim();
  git("init", "-q");
  git("config", "user.name", "Test");
  git("config", "user.email", "test@example.invalid");
  await writeFile(
    path.join(dir, "index.client.tsx"),
    "export const DEMO = null;\n",
  );
  await writeFile(
    path.join(dir, "server/tasks-chunk.ts"),
    "export const TASKS_CHUNK = null;\n",
  );
  git("add", ".");
  git("commit", "-qm", "initial");
  const aliasHome = await mkdtemp(
    path.join(tmpdir(), "paseo-source-state-alias-"),
  );
  await symlink(home, path.join(aliasHome, "home"), "junction");
  const row = {
    id: "better-paseo",
    path: path.join(aliasHome, "home/plugins/better-paseo/1.0.0"),
    installation: {
      identity: { kind: "git", remote: "https://example.invalid/demo.git" },
      currentRevision: git("rev-parse", "HEAD"),
    },
  };
  const after = "export const DEMO = { seasoned: true };\n";
  await writeFile(path.join(dir, "index.client.tsx"), after);
  const profile = {
    patches: [
      {
        plugin: "better-paseo",
        data: {
          files: [{ path: "index.client.tsx", afterSha256: digest(after) }],
        },
      },
    ],
  };
  const state = await sourceState(row, profile);
  assert.equal(state.clean, true);
  assert.deepEqual(state.changed, []);
  // The allowance only covers patched files; any other local edit still
  // counts as dirty seen through the linked prefix.
  await writeFile(
    path.join(dir, "server/tasks-chunk.ts"),
    "export const TASKS_CHUNK = { hand: true };\n",
  );
  const dirty = await sourceState(row, profile);
  assert.equal(dirty.clean, false);
  assert.deepEqual(dirty.changed, ["server/tasks-chunk.ts"]);
});
